bounded_host_request.command:
python3 - <<'PY'
import json,subprocess,sys
repo="G-ACE-inc/server-core"
def api(method,path,data=None):
 args=["gh","api","-X",method,"repos/"+repo+"/"+path]
 if data is not None:args+=["--input","-"]
 p=subprocess.run(args,input=json.dumps(data) if data is not None else None,capture_output=True,text=True,timeout=35)
 if p.returncode:raise RuntimeError("GITHUB_"+path.split("/")[0]+"_REJECTED")
 return json.loads(p.stdout)
try:
 pr=api("GET","pulls/300")
 base=api("GET","branches/main")
 if pr["head"]["sha"]!="641e3391fe01cc2f5451e5070091cf3fcefc72f8" or not pr["draft"] or pr["state"]!="open":raise RuntimeError("PR_CHANGED")
 if base["commit"]["sha"]!="f5d60f79c32c4097363ed71a27a1c3d5bbaf4b0d":raise RuntimeError("MAIN_CHANGED")
 if pr.get("mergeable") is not True:raise RuntimeError("MERGEABILITY_CHANGED")
 result=api("POST","merges",{"base":"main","head":"agent-pool/cu40-failed-job-pagination-20261016","commit_message":"Agent Pool CU40: restore paginated failed-run recovery without Codex review"})
 final=api("GET","pulls/300")
 if final.get("merged") is not True:raise RuntimeError("POST_MERGE_NOT_VERIFIED")
 print("AGENT_POOL_PR300_MERGED="+json.dumps({"merge_sha":result.get("sha"),"pr":300,"merged":True,"draft_review_transition":False},sort_keys=True))
except Exception as e:
 print("AGENT_POOL_PR300_MERGE_FAILED="+str(e)[:90])
 sys.exit(1)
PY
